// StayFit - Site-wide JavaScript
// Initializes global event listeners, modal confirm logic, and SignalR notifications.

(function () {
    'use strict';

    document.addEventListener('DOMContentLoaded', function () {
        initModalConfirm();
        initAutoSubmit();
        initNotifications();
    });

    // --- Modal Confirm ---
    function initModalConfirm() {
        var modalEl = document.getElementById('modalConfirm');
        if (!modalEl) return;

        var bsModal = new bootstrap.Modal(modalEl);
        var confirmBtn = modalEl.querySelector('.modal-confirm-btn');
        var titleEl = modalEl.querySelector('.modal-title');
        var bodyEl = modalEl.querySelector('.modal-body p, .modal-body');
        var pendingForm = null;
        var pendingHref = null;

        document.addEventListener('click', function (e) {
            var trigger = e.target.closest('[data-confirm-title]');
            if (!trigger) return;

            e.preventDefault();
            e.stopPropagation();

            var title = trigger.getAttribute('data-confirm-title') || 'Підтвердження';
            var message = trigger.getAttribute('data-confirm-message') || 'Ви впевнені?';
            var btnText = trigger.getAttribute('data-confirm-btn') || 'Підтвердити';

            if (titleEl) titleEl.textContent = title;
            if (bodyEl) bodyEl.textContent = message;
            if (confirmBtn) confirmBtn.textContent = btnText;

            var form = trigger.closest('form');
            if (trigger.tagName === 'A' && trigger.href) {
                pendingHref = trigger.href;
                pendingForm = null;
            } else if (form) {
                pendingForm = form;
                pendingHref = null;
            }

            bsModal.show();
        });

        if (confirmBtn) {
            confirmBtn.addEventListener('click', function () {
                bsModal.hide();
                if (pendingForm) pendingForm.submit();
                else if (pendingHref) window.location.href = pendingHref;
                pendingForm = null;
                pendingHref = null;
            });
        }
    }

    // --- Auto Submit ---
    function initAutoSubmit() {
        document.querySelectorAll('select[data-auto-submit]').forEach(function (select) {
            select.addEventListener('change', function () {
                var form = this.closest('form');
                if (form) form.submit();
            });
        });
    }

    // --- SignalR Notifications ---
    function initNotifications() {
        if (typeof signalR === 'undefined') return;

        var connection = new signalR.HubConnectionBuilder()
            .withUrl("/notificationHub")
            .withAutomaticReconnect()
            .build();

        connection.on("ReceiveNotification", function (notification) {
            addNotificationToList(notification);
            updateBadge(1);
            showToast(notification);
        });

        connection.start().catch(function (err) {
            console.error("SignalR Connection Error: ", err.toString());
        });

        // Initial fetch
        fetchNotifications();

        // Event listeners for actions
        var markAllBtn = document.getElementById('markAllReadBtn');
        if (markAllBtn) {
            markAllBtn.addEventListener('click', function() {
                fetch('/notifications/mark-all-as-read', { method: 'POST' })
                    .then(r => r.ok && fetchNotifications());
            });
        }

        var clearAllBtn = document.getElementById('clearAllBtn');
        if (clearAllBtn) {
            clearAllBtn.addEventListener('click', function() {
                fetch('/notifications/clear-all', { method: 'POST' })
                    .then(r => r.ok && fetchNotifications());
            });
        }
    }

    function fetchNotifications() {
        fetch('/notifications/unread')
            .then(response => response.json())
            .then(data => {
                var list = document.getElementById('notificationList');
                if (!list) return;

                list.innerHTML = '';
                if (data.length === 0) {
                    list.innerHTML = '<div class="text-center text-muted">Немає сповіщень</div>';
                    updateBadge(0, true);
                    toggleActionButtons(false);
                } else {
                    data.forEach(n => addNotificationToList(n));
                    updateBadge(data.length, true);
                    toggleActionButtons(true);
                }
            });
    }

    function addNotificationToList(n) {
        var list = document.getElementById('notificationList');
        if (!list) return;

        // Remove empty message if present
        var emptyMsg = list.querySelector('.text-muted');
        if (emptyMsg) emptyMsg.remove();

        var item = document.createElement('div');
        item.className = 'notification-item mb-2 p-2 border-bottom';
        item.innerHTML = `
            <div class="d-flex justify-content-between">
                <strong class="small">${n.title}</strong>
                <span class="text-muted smaller">${new Date(n.createdAt).toLocaleTimeString()}</span>
            </div>
            <div class="smaller">${n.message}</div>
        `;
        list.prepend(item);
        toggleActionButtons(true);
    }

    function updateBadge(count, isAbsolute) {
        var badge = document.getElementById('notificationBadge');
        var countEl = document.getElementById('notificationCount');
        if (!badge || !countEl) return;

        var current = isAbsolute ? 0 : parseInt(countEl.textContent) || 0;
        var total = current + count;

        countEl.textContent = total;
        if (total > 0) {
            badge.classList.remove('d-none');
        } else {
            badge.classList.add('d-none');
        }
    }

    function toggleActionButtons(show) {
        var btns = ['markAllReadBtn', 'clearAllBtn'];
        btns.forEach(id => {
            var el = document.getElementById(id);
            if (el) {
                if (show) el.classList.remove('d-none');
                else el.classList.add('d-none');
            }
        });
    }

    function showToast(n) {
        // Simple console log for now, or use a library like toastr if available
        console.log("New Notification:", n.title, n.message);
    }
})();

// --- Theme Toggle ---
function sfToggleTheme() {
    var html = document.documentElement;
    var isDark = html.getAttribute('data-bs-theme') === 'dark';
    var next = isDark ? 'light' : 'dark';
    html.setAttribute('data-bs-theme', next);
    localStorage.setItem('sf-theme', next);
    var icon = document.getElementById('sf-theme-icon');
    if (icon) {
        icon.className = next === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-fill';
    }
}

// Sync icon on load
(function () {
    var t = document.documentElement.getAttribute('data-bs-theme');
    var icon = document.getElementById('sf-theme-icon');
    if (icon) icon.className = t === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-fill';
})();

// Diary Notes Handler
// Handles character counting and note saving for food logs

(function() {
    'use strict';

    // Character counter for notes
    document.querySelectorAll('.note-textarea').forEach(textarea => {
        textarea.addEventListener('input', function() {
            const logId = this.dataset.logId;
            const charCount = document.getElementById(`charcount_${logId}`);
            if (charCount) {
                charCount.textContent = this.value.length;
            }
        });
    });

    // Save note button handler
    document.querySelectorAll('.save-note-btn').forEach(button => {
        button.addEventListener('click', function() {
            const logId = this.dataset.logId;
            const textarea = document.getElementById(`note_${logId}`);
            if (!textarea) {
                return;
            }

            const noteText = textarea.value;
            const originalButtonText = this.innerHTML;
            this.disabled = true;
            this.innerHTML = '<i class="bi bi-hourglass-split"></i> Збереження...';

            fetch(window.diaryUpdateUrl || '/Diary/UpdateFoodLogNote', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                    'X-Requested-With': 'XMLHttpRequest'
                },
                body: `logId=${encodeURIComponent(logId)}&note=${encodeURIComponent(noteText)}`
            })
            .then(response => {
                if (!response.ok) {
                    throw new Error('Network response was not ok');
                }
                return response.json();
            })
            .then(data => {
                if (data.success) {
                    this.innerHTML = '<i class="bi bi-check-circle"></i> Збережено!';
                    setTimeout(() => {
                        this.innerHTML = originalButtonText;
                        this.disabled = false;
                    }, 2000);
                } else {
                    throw new Error(data.error || 'Помилка при збереженні нотатки');
                }
            })
            .catch(error => {
                console.error('Error saving note:', error);
                this.innerHTML = '<i class="bi bi-exclamation-circle"></i> Помилка';
                this.classList.add('btn-danger');
                this.classList.remove('btn-outline-success');
                setTimeout(() => {
                    this.innerHTML = originalButtonText;
                    this.classList.remove('btn-danger');
                    this.classList.add('btn-outline-success');
                    this.disabled = false;
                }, 3000);
            });
        });
    });
})();

(function () {
    const STORAGE_KEY = 'sf_water_' + new Date().toISOString().slice(0, 10);
    const GOAL = 8;

    function load() {
        return parseInt(localStorage.getItem(STORAGE_KEY) || '0', 10);
    }

    function save(val) {
        localStorage.setItem(STORAGE_KEY, val);
    }

    function render(count) {
        const intake = document.getElementById('waterIntake');
        const drops  = document.getElementById('waterDrops');
        const dropsContainer = document.getElementById('waterDrops');
        if (!dropsContainer) return;

        const card = dropsContainer.closest('.card');
        const bar = card ? card.querySelector('.sf-progress-bar') : null;
        
        if (intake) intake.textContent = count;
        if (bar)    bar.style.width = Math.min(count / GOAL * 100, 100) + '%';
        
        dropsContainer.innerHTML = '';
        for (let i = 1; i <= GOAL; i++) {
            const span = document.createElement('span');
            span.className = 'sf-drop' + (i <= count ? ' active' : '');
            span.textContent = '○';
            span.title = i + ' склянка';
            span.addEventListener('click', function () {
                const cur = load();
                const newVal = (i <= cur && i === cur) ? cur - 1 : i;
                save(newVal < 0 ? 0 : newVal);
                render(load());
            });
            dropsContainer.appendChild(span);
        }
    }

    document.addEventListener('DOMContentLoaded', function () {
        if (!document.getElementById('waterDrops')) return;
        
        render(load());
        const resetBtn = document.getElementById('waterResetBtn');
        if (resetBtn) resetBtn.addEventListener('click', function () {
            save(0); render(0);
        });
    });
})();

(function () {
    const STORAGE_KEY = 'sf_water_' + new Date().toISOString().slice(0, 10);
    const HISTORY_KEY = 'sf_water_history_' + new Date().toISOString().slice(0, 10);
    const GOAL = 8;

    function load() {
        return parseInt(localStorage.getItem(STORAGE_KEY) || '0', 10);
    }

    function save(val) {
        localStorage.setItem(STORAGE_KEY, Math.max(0, val));
    }

    function getHistory() {
        try {
            return JSON.parse(localStorage.getItem(HISTORY_KEY) || '[]');
        } catch {
            return [];
        }
    }

    function saveHistory(entries) {
        localStorage.setItem(HISTORY_KEY, JSON.stringify(entries));
    }

    function addToHistory(glasses) {
        const history = getHistory();
        history.push({
            time: new Date().toLocaleTimeString('uk-UA', { hour: '2-digit', minute: '2-digit' }),
            glasses: glasses
        });
        saveHistory(history);
    }

    function render(count) {
        const intake = document.getElementById('waterIntake');
        const drops = document.getElementById('waterDrops');
        const progressBar = document.querySelector('.sf-progress-bar');

        if (intake) intake.textContent = count;
        if (!drops) return;

        // Анімація прогрес бару
        if (progressBar) {
            progressBar.classList.add('pulse');
            setTimeout(() => progressBar.classList.remove('pulse'), 800);
        }

        // Крапельки
        drops.innerHTML = '';
        for (let i = 1; i <= GOAL; i++) {
            const span = document.createElement('span');
            span.className = 'sf-drop' + (i <= count ? ' active' : '');
            span.textContent = '💧';
            span.title = i + ' склянка';
            span.style.cursor = 'pointer';
            span.addEventListener('click', function () {
                const cur = load();
                const newVal = (i <= cur && i === cur) ? cur - 1 : i;
                const final = Math.max(0, newVal);
                const diff = final - cur;
                save(final);
                if (diff > 0) addToHistory(diff);
                render(final);
                updateHistory();
                updateProgressBar(final);
            });
            drops.appendChild(span);
        }
    }

    function updateProgressBar(count) {
        var pct = count / GOAL * 100;
        var displayPct = Math.min(pct, 100);
        var bar = document.querySelector('.sf-progress-bar');
        if (bar) {
            bar.style.width = displayPct + '%';
            bar.className = count > GOAL ? 'sf-progress-bar bg-danger' : 'sf-progress-bar bg-info';
        }
        var label = document.querySelector('.sf-progress-pct');
        if (label) label.textContent = displayPct.toFixed(0) + '%';
        var warning = document.getElementById('waterWarning');
        if (warning) warning.style.display = count > GOAL ? 'block' : 'none';
    }

    function updateHistory() {
        const history = getHistory();
        const container = document.getElementById('waterHistory');
        if (!container) return;
        
        if (history.length === 0) {
            container.innerHTML = '<div class="list-group-item text-muted text-center py-4">Поки немає записів. Почніть додавати воду!</div>';
            return;
        }

        container.innerHTML = history.map((entry, idx) => `
            <div class="list-group-item d-flex justify-content-between align-items-center">
                <div>
                    <span class="fw-semibold">${entry.time}</span>
                    <span class="badge bg-info ms-2">${entry.glasses} ${entry.glasses === 1 ? 'склянка' : 'склянок'}</span>
                </div>
                <button class="btn btn-sm btn-outline-danger" data-idx="${idx}" onclick="removeHistoryEntry(${idx})">
                    ✕
                </button>
            </div>
        `).join('');
    }

    window.removeHistoryEntry = function(idx) {
        const history = getHistory();
        if (idx < 0 || idx >= history.length) return;
        history.splice(idx, 1);
        saveHistory(history);
        updateHistory();
        const total = history.reduce((sum, e) => sum + e.glasses, 0);
        save(total);
        render(total);
        updateProgressBar(total);
    };

    document.addEventListener('DOMContentLoaded', function () {
        if (!document.getElementById('waterHistory')) return;

        const count = load();
        render(count);
        updateHistory();
        updateProgressBar(count);

        document.querySelectorAll('.water-btn').forEach(btn => {
            btn.addEventListener('click', function () {
                const glasses = parseInt(this.dataset.glasses, 10);
                const cur = load();
                const newVal = cur + glasses;
                save(newVal);
                addToHistory(glasses);
                render(newVal);
                updateHistory();
                updateProgressBar(newVal);
                
                this.classList.add('active');
                setTimeout(() => this.classList.remove('active'), 200);
            });
        });

        const resetBtn = document.getElementById('waterResetBtn');
        if (resetBtn) {
            resetBtn.addEventListener('click', function () {
                if (confirm('Ви впевнені? Це скине всі записи на сьогодні.')) {
                    save(0);
                    localStorage.removeItem(HISTORY_KEY);
                    render(0);
                    updateHistory();
                    updateProgressBar(0);
                }
            });
        }
    });
})();

document.addEventListener('DOMContentLoaded', function () {
    var canvas = document.getElementById('progressChart');
    if (!canvas) return;

    var ctx = canvas.getContext('2d');
    
    try {
        var labels = JSON.parse(canvas.dataset.labels || '[]');
        var caloriesData = JSON.parse(canvas.dataset.calories || '[]');
        var goalValue = parseFloat(canvas.dataset.goal || '0');
        var totalDays = parseInt(canvas.dataset.days || '0');
        
        var goalLine = Array(totalDays).fill(goalValue);

        new Chart(ctx, {
            type: 'bar',
            data: {
                labels: labels,
                datasets: [
                    {
                        label: 'Спожито калорій',
                        data: caloriesData,
                        backgroundColor: 'rgba(54, 162, 235, 0.6)',
                        borderColor: 'rgba(54, 162, 235, 1)',
                        borderWidth: 1
                    },
                    {
                        label: 'Ціль калорій',
                        data: goalLine,
                        type: 'line',
                        backgroundColor: 'rgba(255, 99, 132, 1)',
                        borderColor: 'rgba(255, 99, 132, 1)',
                        borderWidth: 2,
                        fill: false,
                        pointRadius: 0
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        });
    } catch (e) {
        console.error('Failed to parse chart data', e);
    }
});

(function () {
    const MAX_SUBJECT = 200;
    const MAX_BODY = 5000;

    const emailTemplates = {
        welcome: {
            subject: 'Добро пожалувати до StayFit!',
            body: '<p>Привіт!</p><p>Благодарим за реєстрацію в <b>StayFit</b> — програмі для контролю харчування та здорового способу життя.</p><p>Почніть з встановлення своїх цілей харчування і слідкуйте за прогресом кожного дня.</p><p><a href="https://stayfit.com/nutrition-goal" style="color: #007bff; text-decoration: none;">Встановити цілі</a></p>'
        },
        update: {
            subject: 'Нове оновлення системи',
            body: '<p>Привіт!</p><p>Ми щойно оновили <b>StayFit</b> з новими функціями:</p><ul><li>Новий інтерфейс відстеження води</li><li>Покращена статистика</li><li>Виправлення помилок</li></ul><p>Дякуємо за використання нашого сервісу!</p>'
        },
        maintenance: {
            subject: 'Планове технічне обслуговування',
            body: '<p>Привіт!</p><p>20 травня 2026 року з 22:00 до 23:00 (UTC) буде проведено планове технічне обслуговування серверів.</p><p>Під час цього часу сервіс може бути недоступний.</p><p>Вибачаємо за незручності!</p>'
        }
    };

    function showMessage(message, type) {
        const msgDiv = document.getElementById('formMessage');
        if (!msgDiv) return;
        msgDiv.className = 'alert alert-' + type;
        msgDiv.textContent = message;
        msgDiv.style.display = 'block';
    }

    function init() {
        const subjectInput = document.getElementById('subject');
        const bodyInput = document.getElementById('htmlBody');
        const form = document.getElementById('broadcastForm');

        if (subjectInput) {
            subjectInput.addEventListener('input', function (e) {
                const count = e.target.value.length;
                const counter = document.getElementById('subjectCount');
                const progress = document.getElementById('subjectProgress');
                if (counter) counter.textContent = count + ' / ' + MAX_SUBJECT;
                if (progress) progress.style.width = (count / MAX_SUBJECT * 100) + '%';
            });
        }

        if (bodyInput) {
            bodyInput.addEventListener('input', function (e) {
                const count = e.target.value.length;
                const counter = document.getElementById('bodyCount');
                const progress = document.getElementById('bodyProgress');
                if (counter) counter.textContent = count + ' / ' + MAX_BODY;
                if (progress) progress.style.width = (count / MAX_BODY * 100) + '%';
            });
        }

        if (form) {
            form.addEventListener('submit', async function (e) {
                e.preventDefault();

                const subject = document.getElementById('subject').value.trim();
                const htmlBody = document.getElementById('htmlBody').value.trim();

                if (!subject || !htmlBody) {
                    showMessage('Заповніть усі поля', 'warning');
                    return;
                }

                const sendBtn = document.getElementById('sendBtn');
                sendBtn.disabled = true;
                sendBtn.innerHTML = 'Відправлення...';

                try {
                    const response = await fetch('/admin/email/send', {
                        method: 'POST',
                        headers: {
                            'Content-Type': 'application/json'
                        },
                        body: JSON.stringify({ subject, htmlBody })
                    });

                    const data = await response.json();

                    if (response.ok) {
                        showMessage(data.message, 'success');
                        form.reset();
                        document.getElementById('subjectCount').textContent = '0 / 200';
                        document.getElementById('bodyCount').textContent = '0 / 5000';
                        document.getElementById('subjectProgress').style.width = '0%';
                        document.getElementById('bodyProgress').style.width = '0%';
                        setTimeout(() => location.reload(), 2000);
                    } else {
                        showMessage(data.message, 'danger');
                    }
                } catch (error) {
                    showMessage('Помилка: ' + error.message, 'danger');
                } finally {
                    sendBtn.disabled = false;
                    sendBtn.innerHTML = 'Відправити';
                }
            });
        }

        // Global functions for buttons
        window.loadTemplate = function(templateName) {
            const template = emailTemplates[templateName];
            if (template) {
                const s = document.getElementById('subject');
                const b = document.getElementById('htmlBody');
                if (s) s.value = template.subject;
                if (b) b.value = template.body;
                if (s) s.dispatchEvent(new Event('input'));
                if (b) b.dispatchEvent(new Event('input'));
                showMessage('Шаблон завантажено', 'info');
            }
        };

        window.viewBroadcast = function(subject, htmlBody) {
            const ps = document.getElementById('previewSubject');
            const pb = document.getElementById('previewBody');
            if (ps) ps.textContent = subject;
            if (pb) pb.innerHTML = decodeURIComponent(htmlBody);
            const modalEl = document.getElementById('previewModal');
            if (modalEl) {
                const modal = new bootstrap.Modal(modalEl);
                modal.show();
            }
        };

        const previewBtn = document.querySelector('[data-bs-target="#previewModal"]');
        if (previewBtn) {
            previewBtn.addEventListener('click', function() {
                const subject = document.getElementById('subject').value.trim();
                const htmlBody = document.getElementById('htmlBody').value.trim();
                
                if (!subject || !htmlBody) {
                    showMessage('Заповніть тему та текст листа для перегляду', 'warning');
                    return false;
                }
                
                const ps = document.getElementById('previewSubject');
                const pb = document.getElementById('previewBody');
                if (ps) ps.textContent = subject;
                if (pb) pb.innerHTML = htmlBody;
            });
        }
    }

    document.addEventListener('DOMContentLoaded', init);
})();

(function () {
    const form     = document.getElementById('sf-ps-form');
    const results  = document.getElementById('sf-ps-results');
    const skeleton = document.getElementById('sf-ps-skeleton');
    const btn      = document.getElementById('sf-ps-btn');

    if (!form) return;

    form.addEventListener('submit', function (e) {
        e.preventDefault();

        const url = new URL(form.action || location.href, location.origin);
        url.searchParams.delete('page');
        new FormData(form).forEach((v, k) => {
            if (v) url.searchParams.set(k, v);
            else   url.searchParams.delete(k);
        });

        if (results) results.classList.add('d-none');
        if (skeleton) skeleton.classList.remove('d-none');
        if (btn) btn.disabled = true;

        history.pushState(null, '', url.toString());

        fetch(url.toString(), { headers: { 'X-Requested-With': 'XMLHttpRequest' } })
            .then(r => r.text())
            .then(html => {
                const doc   = new DOMParser().parseFromString(html, 'text/html');
                const fresh = doc.getElementById('sf-ps-results');
                if (fresh && results) results.innerHTML = fresh.innerHTML;
            })
            .catch(() => { location.href = url.toString(); })
            .finally(() => {
                if (skeleton) skeleton.classList.add('d-none');
                if (results) results.classList.remove('d-none');
                if (btn) btn.disabled = false;
            });
    });
})();

(function () {
    // --- SECURITY TAB ACTIVATION ---
    document.addEventListener('DOMContentLoaded', function() {
        const container = document.querySelector('[data-profile-security-active]');
        if (container && container.dataset.profileSecurityActive === 'true') {
            const securityTab = document.getElementById('security-tab');
            if (securityTab) {
                const tab = new bootstrap.Tab(securityTab);
                tab.show();
            }
        }
    });

    // --- FORM VALIDATIONS ---
    document.addEventListener('DOMContentLoaded', function() {
        const changePasswordForm = document.querySelector('form[action="/account-security/change-password"]');
        if (changePasswordForm) {
            changePasswordForm.addEventListener('submit', function (e) {
                const newPassword = document.getElementById('newPassword').value;
                const confirmPassword = document.getElementById('confirmPassword').value;

                if (newPassword !== confirmPassword) {
                    e.preventDefault();
                    alert('Паролі не збігаються!');
                    return false;
                }
            });
        }

        const deleteForm = document.querySelector('form[action="/account-security/delete-account"]');
        if (deleteForm) {
            deleteForm.addEventListener('submit', function (e) {
                const password = document.getElementById('deletePassword').value;
                if (!password || password.trim() === '') {
                    e.preventDefault();
                    alert('Будь ласка, введіть пароль для підтвердження.');
                    return false;
                }
                
                if (!confirm('ОСТАННЄ ПОПЕРЕДЖЕННЯ! Ви дійсно хочете видалити акаунт назавжди?')) {
                    e.preventDefault();
                    return false;
                }
            });
        }
    });

    // --- SECURITY LOGS ---
    async function loadSecurityLogs(page = 1) {
        const container = document.getElementById('securityLogs');
        if (!container) return;

        try {
            const eventType = document.getElementById('securityEventTypeFilter')?.value || '';
            let requestUrl = '/security-log/logs?page=' + page;

            if (eventType) {
                requestUrl += '&eventType=' + encodeURIComponent(eventType);
            }

            const response = await fetch(requestUrl);
            if (!response.ok) {
                let errorMessage = 'Помилка при завантаженні журналу';
                try {
                    const errorPayload = await response.json();
                    if (errorPayload?.message) {
                        errorMessage = errorPayload.message;
                    }
                } catch (_) {}
                throw new Error(errorMessage);
            }
            
            const data = await response.json();
            renderSecurityLogs(data);
        } catch (error) {
            console.error('Помилка завантаження логів:', error);
            container.innerHTML = 
                '<div class="alert alert-warning"><i class="bi bi-exclamation-triangle"></i> Не вдалося завантажити історію безпеки: ' + (error?.message || 'невідома помилка') + '</div>';
        }
    }

    function renderSecurityLogs(pagedResult) {
        const container = document.getElementById('securityLogs');
        if (!container) return;

        if (!pagedResult || typeof pagedResult !== 'object') {
            container.innerHTML = '<div class="alert alert-warning"><i class="bi bi-exclamation-triangle"></i> Сервер повернув некоректні дані журналу безпеки.</div>';
            return;
        }

        const items = pagedResult.items || pagedResult.Items || [];
        const pageNumber = pagedResult.pageNumber || pagedResult.PageNumber || 1;
        const totalPages = pagedResult.totalPages || pagedResult.TotalPages || 1;
        const totalCount = pagedResult.totalCount || pagedResult.TotalCount || 0;
        
        if (!items.length) {
            container.innerHTML = '<p class="text-muted">Немає записів у журналі безпеки.</p>';
            return;
        }

        let html = '<div class="table-responsive">';
        html += '<table class="table table-sm table-hover align-middle mb-0">';
        html += '<thead class="table-light"><tr>';
        html += '<th>Дата/Час</th><th>Тип івенту</th><th>Опис</th><th>Пристрій</th><th>IP адреса</th><th>Статус</th>';
        html += '</tr></thead><tbody>';

        items.forEach(log => {
            const date = new Date(log.createdAt);
            const formattedDate = date.toLocaleDateString('uk-UA') + ' ' + date.toLocaleTimeString('uk-UA');
            const statusBadge = log.status === 'Success' 
                ? '<span class="badge bg-success"><i class="bi bi-check-lg"></i> Успіх</span>'
                : '<span class="badge bg-danger"><i class="bi bi-x-lg"></i> Помилка</span>';
            
            let eventBadge = '';
            switch(log.eventType) {
                case 'Login': eventBadge = '<span class="badge bg-info"><i class="bi bi-box-arrow-in-right"></i> Вхід</span>'; break;
                case 'Logout': eventBadge = '<span class="badge bg-secondary"><i class="bi bi-box-arrow-right"></i> Вихід</span>'; break;
                case 'PasswordChange': eventBadge = '<span class="badge bg-warning"><i class="bi bi-key"></i> Зміна пароля</span>'; break;
                case 'SessionTerminated': eventBadge = '<span class="badge bg-danger"><i class="bi bi-stop-circle"></i> Сеанс завершено</span>'; break;
                default: eventBadge = '<span class="badge bg-dark">' + log.eventType + '</span>';
            }
            
            html += '<tr>';
            html += '<td>' + formattedDate + '</td>';
            html += '<td>' + eventBadge + '</td>';
            html += '<td>' + log.description + '</td>';
            html += '<td>' + (log.deviceSummary || 'Unknown') + '</td>';
            html += '<td>' + (log.ipAddress || '—') + '</td>';
            html += '<td>' + statusBadge + '</td>';
            html += '</tr>';
        });

        html += '</tbody></table></div>';
        
        if (totalPages > 1) {
            html += '<p class="text-muted small mt-3">Сторінка ' + pageNumber + ' з ' + totalPages + 
                    ' (' + totalCount + ' записів)</p>';
        }
        
        container.innerHTML = html;
    }

    document.addEventListener('DOMContentLoaded', function() {
        const filter = document.getElementById('securityEventTypeFilter');
        if (filter) {
            filter.addEventListener('change', () => loadSecurityLogs(1));
        }
        if (document.getElementById('securityLogs')) {
            loadSecurityLogs(1);
        }
    });

    // --- METRICS & AUTO-SAVE ---
    document.addEventListener('DOMContentLoaded', function() {
        const inputs = ['Weight', 'Height', 'DateOfBirth', 'Gender', 'ActivityLevel', 'FullName'];
        const elements = {};
        inputs.forEach(id => {
            const el = document.getElementById(id);
            if (el) elements[id] = el;
        });

        const bmiEl = document.getElementById('calc-bmi');
        const bmrEl = document.getElementById('calc-bmr');
        const tdeeEl = document.getElementById('calc-tdee');
        const saveIndicator = document.getElementById('auto-save-indicator');

        if (!bmiEl) return; // Not on edit profile page or similar

        function calculateMetrics() {
            const weight = parseFloat(elements.Weight?.value);
            const height = parseFloat(elements.Height?.value);
            const gender = elements.Gender?.value;
            const dob = elements.DateOfBirth?.value;
            const activity = elements.ActivityLevel?.value;

            if (!weight || !height) {
                if (bmiEl) bmiEl.innerText = '-';
                if (bmrEl) bmrEl.innerText = '- ккал';
                if (tdeeEl) tdeeEl.innerText = '- ккал';
                return;
            }

            const heightM = height / 100;
            const bmi = weight / (heightM * heightM);
            if (bmiEl) bmiEl.innerText = bmi.toFixed(1);

            let age = 30;
            if (dob) {
                const birthDate = new Date(dob);
                const today = new Date();
                age = today.getFullYear() - birthDate.getFullYear();
                const m = today.getMonth() - birthDate.getMonth();
                if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
                    age--;
                }
            }

            let bmr = 0;
            if (gender === 'Чоловік') {
                bmr = (10 * weight) + (6.25 * height) - (5 * age) + 5;
            } else if (gender === 'Жінка') {
                bmr = (10 * weight) + (6.25 * height) - (5 * age) - 161;
            } else {
                bmr = (10 * weight) + (6.25 * height) - (5 * age) - 78;
            }
            if (bmrEl) bmrEl.innerText = Math.round(bmr) + ' ккал';

            let activityMultiplier = 1.2;
            switch(activity) {
                case 'LightlyActive': activityMultiplier = 1.375; break;
                case 'ModeratelyActive': activityMultiplier = 1.55; break;
                case 'VeryActive': activityMultiplier = 1.725; break;
                case 'SuperActive': activityMultiplier = 1.9; break;
            }

            const tdee = bmr * activityMultiplier;
            if (tdeeEl) tdeeEl.innerText = Math.round(tdee) + ' ккал';
        }

        let saveTimeout = null;

        async function autoSave() {
            if (saveIndicator) {
                saveIndicator.innerText = "Зберігається...";
                saveIndicator.classList.remove('bg-success', 'd-none');
                saveIndicator.classList.add('bg-warning', 'text-dark');
            }

            const payload = {
                FullName: elements.FullName?.value || '',
                Weight: parseFloat(elements.Weight?.value) || null,
                Height: parseFloat(elements.Height?.value) || null,
                DateOfBirth: elements.DateOfBirth?.value || null,
                Gender: elements.Gender?.value || null,
                ActivityLevel: elements.ActivityLevel?.value || null
            };

            try {
                const response = await fetch('/profile/auto-save', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                        'RequestVerificationToken': document.querySelector('input[name="__RequestVerificationToken"]')?.value
                    },
                    body: JSON.stringify(payload)
                });

                if (response.ok) {
                    if (saveIndicator) {
                        saveIndicator.innerText = "Збережено ✔️";
                        saveIndicator.classList.remove('bg-warning', 'text-dark');
                        saveIndicator.classList.add('bg-success');
                        setTimeout(() => saveIndicator.classList.add('d-none'), 3000);
                    }
                } else {
                    if (saveIndicator) {
                        saveIndicator.innerText = "Помилка";
                        saveIndicator.classList.remove('bg-warning', 'text-dark');
                        saveIndicator.classList.add('bg-danger');
                    }
                }
            } catch (error) {
                console.error("Auto-save error", error);
                if (saveIndicator) {
                    saveIndicator.innerText = "Помилка";
                    saveIndicator.classList.remove('bg-warning', 'text-dark');
                    saveIndicator.classList.add('bg-danger');
                }
            }
        }

        inputs.forEach(id => {
            if (elements[id]) {
                elements[id].addEventListener('input', function() {
                    calculateMetrics();
                    clearTimeout(saveTimeout);
                    saveTimeout = setTimeout(autoSave, 1500);
                });
            }
        });

        calculateMetrics();
    });
})();

(function () {
    // --- LOGIN FORM ---
    const loginForm = document.getElementById('loginForm');
    if (loginForm) {
        const emailInput = document.getElementById('emailInput');
        const passwordInput = document.getElementById('passwordInput');
        const submitBtn = document.getElementById('submitBtn');
        const submitText = document.getElementById('submitText');
        const submitSpinner = document.getElementById('submitSpinner');
        const loginAlert = document.getElementById('loginAlert');
        const loginAlertText = document.getElementById('loginAlertText');
        const retryBtn = document.getElementById('retryBtn');

        const validateEmail = (email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

        const checkValidity = (element, validator) => {
            if (element.value.trim() === '') {
                element.classList.remove('is-invalid', 'is-valid');
                return false;
            }
            const isValid = validator(element.value);
            if (isValid) {
                element.classList.remove('is-invalid');
                element.classList.add('is-valid');
            } else {
                element.classList.remove('is-valid');
                element.classList.add('is-invalid');
            }
            return isValid;
        };

        if (emailInput) emailInput.addEventListener('input', () => checkValidity(emailInput, validateEmail));
        if (passwordInput) passwordInput.addEventListener('input', () => checkValidity(passwordInput, val => val.length >= 8));

        loginForm.addEventListener('submit', async function (e) {
            e.preventDefault();
            const isEmailValid = checkValidity(emailInput, validateEmail);
            const isPasswordValid = checkValidity(passwordInput, val => val.length >= 8);
            if (!isEmailValid || !isPasswordValid) return;
            submitLoginForm();
        });

        if (retryBtn) retryBtn.addEventListener('click', () => {
            loginAlert.classList.add('d-none');
            submitLoginForm();
        });

        async function submitLoginForm() {
            submitBtn.disabled = true;
            if (submitText) submitText.classList.add('opacity-0');
            if (submitSpinner) submitSpinner.classList.remove('d-none');
            if (loginAlert) loginAlert.classList.add('d-none');

            try {
                const response = await fetch(loginForm.action, {
                    method: 'POST',
                    body: new FormData(loginForm),
                    headers: { 'X-Requested-With': 'XMLHttpRequest' }
                });

                if (response.redirected) {
                    submitBtn.classList.replace('btn-primary', 'btn-success');
                    if (submitSpinner) submitSpinner.classList.add('d-none');
                    if (submitText) {
                        submitText.innerHTML = '<i class="bi bi-check2-circle me-2"></i>Успішно';
                        submitText.classList.remove('opacity-0');
                    }
                    setTimeout(() => window.location.href = response.url, 500);
                    return;
                }

                const html = await response.text();
                const doc = new DOMParser().parseFromString(html, 'text/html');
                const errors = doc.querySelector('.validation-summary-errors');
                if (errors) {
                    if (loginAlertText) loginAlertText.textContent = errors.textContent.trim();
                    if (loginAlert) loginAlert.classList.remove('d-none');
                    emailInput.classList.add('is-invalid');
                    passwordInput.classList.add('is-invalid');
                } else {
                    window.location.reload();
                }
            } catch (error) {
                if (loginAlertText) loginAlertText.textContent = 'Помилка з\'єднання. Перевірте інтернет.';
                if (loginAlert) loginAlert.classList.remove('d-none');
            } finally {
                submitBtn.disabled = false;
                if (submitText) submitText.classList.remove('opacity-0');
                if (submitSpinner) submitSpinner.classList.add('d-none');
            }
        }
    }

    // --- REGISTER FORM ---
    const regForm = document.getElementById('registerForm');
    if (regForm) {
        const password = document.getElementById('password');
        const confirmPassword = document.getElementById('confirmPassword');
        const confirmError = document.getElementById('confirmPasswordError');

        const checkPasswords = () => {
            if (confirmPassword.value && password.value !== confirmPassword.value) {
                confirmPassword.classList.add('is-invalid');
                confirmError.textContent = "Паролі не співпадають";
                return false;
            } else if (confirmPassword.value) {
                confirmPassword.classList.replace('is-invalid', 'is-valid');
                confirmError.textContent = "";
                return true;
            }
            return true;
        };

        if (password) password.addEventListener('input', checkPasswords);
        if (confirmPassword) confirmPassword.addEventListener('input', checkPasswords);

        regForm.addEventListener('submit', function (e) {
            if (!regForm.checkValidity() || !checkPasswords()) {
                e.preventDefault();
                e.stopPropagation();
                Array.from(regForm.elements).forEach(input => {
                    if (!input.checkValidity()) input.classList.add('is-invalid');
                });
            } else {
                const btn = document.getElementById('submitBtn');
                if (btn) btn.disabled = true;
                const txt = document.getElementById('submitText');
                if (txt) txt.classList.add('opacity-0');
                const spn = document.getElementById('submitSpinner');
                if (spn) spn.classList.remove('d-none');
            }
            regForm.classList.add('was-validated');
        });
    }

    // --- FORGOT PASSWORD ---
    const forgotForm = document.getElementById('forgotForm');
    if (forgotForm) {
        const emailInput = document.getElementById('emailInput');
        const submitBtn = document.getElementById('submitBtn');
        const resendBtn = document.getElementById('resendBtn');
        
        forgotForm.addEventListener('submit', e => {
            e.preventDefault();
            if (!emailInput.value.trim() || !emailInput.checkValidity()) {
                emailInput.classList.add('is-invalid');
                return;
            }
            submitForgot();
        });

        if (resendBtn) resendBtn.addEventListener('click', submitForgot);

        async function submitForgot() {
            submitBtn.disabled = true;
            const alertMsg = document.getElementById('alertMsg');
            if (alertMsg) alertMsg.classList.add('d-none');

            try {
                const response = await fetch(forgotForm.action, {
                    method: 'POST',
                    body: new FormData(forgotForm),
                    headers: { 'X-Requested-With': 'XMLHttpRequest' }
                });

                if (response.ok || response.redirected) {
                    document.getElementById('step1')?.classList.add('d-none');
                    document.getElementById('step2')?.classList.remove('d-none');
                    document.getElementById('sentEmail').textContent = emailInput.value;
                } else {
                    if (alertMsg) {
                        alertMsg.textContent = 'Не вдалося надіслати запит.';
                        alertMsg.classList.remove('d-none');
                    }
                }
            } catch (err) {
                if (alertMsg) {
                    alertMsg.textContent = 'Помилка мережі.';
                    alertMsg.classList.remove('d-none');
                }
            } finally {
                submitBtn.disabled = false;
            }
        }
    }
})();

(function () {
    // Character counter for notes
    document.querySelectorAll('.meal-note').forEach(textarea => {
        textarea.addEventListener('input', function() {
            const mealId = this.getAttribute('data-meal-id');
            const counter = document.getElementById(`charcount_${mealId}`);
            if (counter) counter.textContent = this.value.length;
        });
    });

    // Update note button handler
    document.querySelectorAll('.update-note-btn').forEach(btn => {
        btn.addEventListener('click', function() {
            const mealId = this.getAttribute('data-meal-id');
            const noteText = document.getElementById(`note_${mealId}`).value;
            const actionUrl = this.getAttribute('data-action-url');

            if (!actionUrl) {
                console.error('Action URL not found on button');
                return;
            }

            fetch(actionUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/x-www-form-urlencoded',
                },
                body: `mealId=${mealId}&note=${encodeURIComponent(noteText)}`
            })
            .then(response => response.json())
            .then(data => {
                if (data.success) {
                    alert('Нотатка збережена!');
                } else {
                    alert(data.error || 'Помилка при збереженні нотатки');
                }
            })
            .catch(error => {
                console.error('Error:', error);
                alert('Помилка при збереженні нотатки');
            });
        });
    });
})();

(function () {
    const form     = document.getElementById('sf-fi-form');
    const skeleton = document.getElementById('sf-fi-skeleton');
    const results  = document.getElementById('sf-fi-results');
    const btn      = document.getElementById('sf-fi-btn');
    const btnText  = document.getElementById('sf-fi-btn-text');
    const btnSpin  = document.getElementById('sf-fi-btn-spinner');

    if (!form) return;

    form.addEventListener('submit', function (e) {
        e.preventDefault();

        const url = new URL(form.action || location.href, location.origin);
        new FormData(form).forEach((v, k) => {
            if (v) url.searchParams.set(k, v);
            else   url.searchParams.delete(k);
        });

        if (results) results.classList.add('d-none');
        if (skeleton) skeleton.classList.remove('d-none');
        if (btn) btn.disabled = true;
        if (btnText) btnText.classList.add('d-none');
        if (btnSpin) btnSpin.classList.remove('d-none');

        history.pushState(null, '', url.toString());

        fetch(url.toString(), { headers: { 'X-Requested-With': 'XMLHttpRequest' } })
            .then(r => r.text())
            .then(html => {
                const doc   = new DOMParser().parseFromString(html, 'text/html');
                const fresh = doc.getElementById('sf-fi-results');
                if (fresh && results) results.innerHTML = fresh.innerHTML;
            })
            .catch(() => { location.href = url.toString(); })
            .finally(() => {
                if (skeleton) skeleton.classList.add('d-none');
                if (results) results.classList.remove('d-none');
                if (btn) btn.disabled = false;
                if (btnText) btnText.classList.remove('d-none');
                if (btnSpin) btnSpin.classList.add('d-none');
            });
    });
})();

(function () {
    // ── Категорія ─────────────────────────────────────────────────────────
    const catInput = document.getElementById('categoryInput');
    if (catInput) {
        document.querySelectorAll('.sf-cat-btn').forEach(btn => {
            btn.addEventListener('click', function () {
                document.querySelectorAll('.sf-cat-btn').forEach(b => b.classList.remove('active'));
                this.classList.add('active');
                catInput.value = this.dataset.value;
            });
        });
    }

    // ── Попередній перегляд порції ────────────────────────────────────────
    const inpCal  = document.getElementById('inp_cal');
    const inpProt = document.getElementById('inp_prot');
    const inpFat  = document.getElementById('inp_fat');
    const inpCarb = document.getElementById('inp_carb');
    const inpG    = document.getElementById('previewGrams');

    const prevCal  = document.getElementById('prev_cal');
    const prevProt = document.getElementById('prev_prot');
    const prevFat  = document.getElementById('prev_fat');
    const prevCarb = document.getElementById('prev_carb');

    function calcPreview() {
        if (!inpG || !prevCal) return;
        
        const g    = parseFloat(inpG.value)    || 0;
        const cal  = parseFloat(inpCal?.value)  || 0;
        const prot = parseFloat(inpProt?.value) || 0;
        const fat  = parseFloat(inpFat?.value)  || 0;
        const carb = parseFloat(inpCarb?.value) || 0;
        const k = g / 100;
        
        if (prevCal) prevCal.textContent  = g ? (cal  * k).toFixed(0) : '–';
        if (prevProt) prevProt.textContent = g ? (prot * k).toFixed(1) : '–';
        if (prevFat) prevFat.textContent  = g ? (fat  * k).toFixed(1) : '–';
        if (prevCarb) prevCarb.textContent = g ? (carb * k).toFixed(1) : '–';
    }

    if (inpG) {
        [inpCal, inpProt, inpFat, inpCarb, inpG].forEach(el => {
            if (el) el.addEventListener('input', calcPreview);
        });
        calcPreview();
    }
})();
